import{_ as t,o,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"Why does the dashboard not start?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/04.fehlerbehebung/01.dashboard-startet-nicht.md"},"headers":[],"relativePath":"adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md","filePath":"adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md","lastUpdated":1795562976000}'),n={name:"adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md"};function r(d,e,h,i,l,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="why-does-the-dashboard-not-start" tabindex="-1">Why does the dashboard not start? <a class="header-anchor" href="#why-does-the-dashboard-not-start" aria-label="Permalink to &quot;Why does the dashboard not start?&quot;">​</a></h1><p><a id="dashboard-not-start-pillow-esphome"></a></p><h2 id="why-does-the-dashboard-not-start-and-what-does-the-log-say" tabindex="-1">Why does the dashboard not start, and what does the log say? <a class="header-anchor" href="#why-does-the-dashboard-not-start-and-what-does-the-log-say" aria-label="Permalink to &quot;Why does the dashboard not start, and what does the log say?&quot;">​</a></h2><p>The start log in the ESPHome tab shows the reason, the same messages are in the instance log. Most often the selected version cannot be installed. A fixed ESPHome version such as <code>2026.6.5</code> with &quot;Auto Detect&quot; for Pillow and Device Builder helps.</p><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td>&quot;Fatal error starting ESPHomeDashboard&quot;</td><td>The installation failed, often because pip cannot resolve the version combination.</td><td>Reset the versions as described below.</td></tr><tr><td>&quot;ESPHome Dashboard could not be started, &quot;…&quot; is missing in the Python environment&quot;</td><td>The Python environment is incomplete.</td><td>Reset the Python environment, see <a href="#clear-autopy-cache-if-python">below</a>.</td></tr><tr><td>&quot;ESPHome Dashboard stopped (exit code …)&quot;</td><td>The dashboard ended after starting.</td><td>The <code>[ESPHome - Console]</code> lines before it name the reason, see the <a href="#log-only-say-esphome-dashboard">next section</a>.</td></tr><tr><td>&quot;ESPHome Dashboard container … was not created&quot;</td><td>Docker is missing, not running, or the image could not be pulled.</td><td>Check Docker or turn off &quot;Use Docker Integration (Beta)&quot;.</td></tr></tbody></table><h3 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h3><ol><li>Open the instance settings, tab &quot;ESPHome Dashboard&quot;.</li><li>Set &quot;ESPHome Dashboard version&quot; to <code>2026.6.5</code> or to the version that ran last.</li><li>Under &quot;Advanced&quot;, set &quot;Pillow version&quot; and &quot;ESPHome Device Builder version&quot; to &quot;Auto Detect&quot;.</li><li>Save. The instance restarts and installs the versions.</li><li>It worked when the start log shows &quot;ESPHome Dashboard is reachable on port …&quot; and the dashboard appears in the tab.</li></ol><p>If it still does not start, the Python environment is often damaged, for example after an interrupted download: <a href="#clear-autopy-cache-if-python">How do I reset the Python environment?</a></p><p><strong>See also:</strong> <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">How do I choose or update the ESPHome dashboard version, including older ones?</a></p><p><a id="about-please-install-pillow-python"></a></p><h2 id="what-to-do-about-please-install-the-pillow-python-package" tabindex="-1">What to do about &quot;Please install the pillow python package&quot;? <a class="header-anchor" href="#what-to-do-about-please-install-the-pillow-python-package" aria-label="Permalink to &quot;What to do about &quot;Please install the pillow python package&quot;?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="log-only-say-esphome-dashboard"></a></p><h2 id="why-does-the-dashboard-stop-after-a-new-esphome-version" tabindex="-1">Why does the dashboard stop after a new ESPHome version? <a class="header-anchor" href="#why-does-the-dashboard-stop-after-a-new-esphome-version" aria-label="Permalink to &quot;Why does the dashboard stop after a new ESPHome version?&quot;">​</a></h2><p>The new version cannot be installed or started on your system. The adapter logs the reason as an error with <code>[ESPHome - Console]</code>, right before &quot;ESPHome Dashboard stopped (exit code …)&quot;. Go back to the version that ran last.</p><h3 id="how-to-do-it-1" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it-1" aria-label="Permalink to &quot;How to do it&quot;">​</a></h3><ol><li>Open the instance settings, tab &quot;ESPHome Dashboard&quot;.</li><li>If &quot;ESPHome Dashboard version&quot; shows &quot;Always last available&quot; or the new version, enter the version that ran last, or <code>2026.6.5</code>.</li><li>Check under &quot;Advanced&quot; that &quot;Pillow version&quot; is set to &quot;Auto Detect&quot;.</li><li>Save. The instance restarts and installs the version. This takes a few minutes.</li><li>It worked when no further &quot;ESPHome Dashboard stopped&quot; follows in the log.</li></ol><p>Regular dashboard messages only show in the log at log level &quot;debug&quot;. Errors always appear.</p><p><strong>See also:</strong> <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">How do I choose or update the ESPHome dashboard version, including older ones?</a></p><p><a id="clear-autopy-cache-if-python"></a></p><h2 id="how-do-i-reset-the-python-environment-when-it-is-broken" tabindex="-1">How do I reset the Python environment when it is broken? <a class="header-anchor" href="#how-do-i-reset-the-python-environment-when-it-is-broken" aria-label="Permalink to &quot;How do I reset the Python environment when it is broken?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="about-permission-denied-missing-yaml"></a></p><h2 id="what-to-do-about-permission-denied-or-a-missing-yaml-folder" tabindex="-1">What to do about permission denied or a missing YAML folder? <a class="header-anchor" href="#what-to-do-about-permission-denied-or-a-missing-yaml-folder" aria-label="Permalink to &quot;What to do about permission denied or a missing YAML folder?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',25)])])}const c=t(n,[["render",r]]);export{b as __pageData,c as default};
